        raise ValueError('This is a public key')

    kid = tokens.get('kid')
    if 'd' in tokens and not is_private:
        # filter out private fields
        tokens = {k: tokens[k] for k in tokens if k in self.PUBLIC_KEY_FIELDS}
        tokens['kty'] = self.kty
