        if 'redirect_uri' not in kwargs:
            kwargs['redirect_uri'] = self.redirect_uri
        return prepare_token_request(grant_type, body, **kwargs)

    if 'scope' not in kwargs and self.scope:
        kwargs['scope'] = self.scope
    return prepare_token_request(grant_type, body, **kwargs)

